// Turns the node's output into short alerts. It compares each message with the last
// one and sends one msg per change: msg.topic is a short title, msg.payload the text.
//
// ===== EDIT THESE =====
const ALERT_CHARGING = true;        // charging_now started / stopped
const ALERT_BOOST = true;           // boosting started / ended
const ALERT_ERRORS = true;          // any *_error field becoming set or changing
const ALERT_RECOVERY = true;        // also say when an error clears
const ALERT_DEVICE_ALERTS = true;   // new Octopus alerts for the car or charge point (device_alerts)
const DEVICE_ALERT_MAX_AGE_HOURS = 24; // skip device alerts older than this
const IGNORE_ERRORS = ['update_check_error']; // *_error fields you do not want alerts for
// ======================

const p = msg.payload;
if (!p || typeof p !== 'object') return null;

const prev = context.get('prev');
const keepBool = (v, old) => (typeof v === 'boolean' ? v : old);

// Keep only what is compared, not the whole payload. charging_now and boosting can
// be null for a while (for example during an Octopus outage): the last known value is kept.
const snap = {
    charging_now: keepBool(p.charging_now, prev ? prev.charging_now : null),
    boosting: keepBool(p.boosting, prev ? prev.boosting : null),
    errors: {},
    alerts: (Array.isArray(p.device_alerts) ? p.device_alerts : [])
        .map((a) => `${a.published_at}|${a.message}`),
};
for (const [k, v] of Object.entries(p)) {
    if (k.endsWith('_error') && !IGNORE_ERRORS.includes(k)) snap.errors[k] = v || null;
}
context.set('prev', snap);

// The first message after a deploy or restart only sets the baseline.
if (!prev) return null;

const out = [];
const say = (topic, text) => out.push({ topic, payload: text });

if (ALERT_CHARGING && typeof prev.charging_now === 'boolean' && prev.charging_now !== snap.charging_now) {
    if (snap.charging_now) {
        const why = snap.boosting ? 'boost' : 'planned slot';
        say('Charging started', `Charging started (${why}). Target ${p.confirmed_limit}% by ${p.confirmed_time}.`);
    } else {
        const next = p.next_start_locale ? ` Next slot starts ${p.next_start_locale}.` : '';
        say('Charging stopped', `Charging stopped.${next}`);
    }
}

if (ALERT_BOOST && typeof prev.boosting === 'boolean' && prev.boosting !== snap.boosting) {
    say(snap.boosting ? 'Boost started' : 'Boost ended',
        snap.boosting ? 'A boost charge has started.' : 'The boost charge has ended.');
}

if (ALERT_ERRORS) {
    const label = (k) => k.replace(/_error$/, '').replace(/_/g, ' ');
    const keys = new Set([...Object.keys(prev.errors), ...Object.keys(snap.errors)]);
    for (const k of keys) {
        const was = prev.errors[k] || null;
        const is = snap.errors[k] || null;
        if (!was && is) say(`Error: ${label(k)}`, `${label(k)}: ${is}`);
        else if (was && is && was !== is) say(`Error: ${label(k)}`, `${label(k)} (changed): ${is}`);
        else if (was && !is && ALERT_RECOVERY) say(`Recovered: ${label(k)}`, `${label(k)}: error cleared.`);
    }
}

if (ALERT_DEVICE_ALERTS) {
    const seen = new Set(prev.alerts);
    const cutoff = Date.now() - DEVICE_ALERT_MAX_AGE_HOURS * 3600000;
    for (const a of p.device_alerts || []) {
        const key = `${a.published_at}|${a.message}`;
        const at = Date.parse(a.published_at);
        if (seen.has(key) || !a.message || (Number.isFinite(at) && at < cutoff)) continue;
        say('Octopus device alert', a.message);
    }
}

return out.length ? [out] : null;
